function bitsetCreate(n){
  var words=Math.ceil(n/32)||1;
  var arr=new Array(words); for(var i=0;i<words;i++) arr[i]=0;
  return {n:n, words:words, arr:arr};
}
function bitsetSet(bs,i){
  if(i<0||i>=bs.n) throw new Error('BIT_OUT_OF_RANGE');
  var w=(i/32)|0, b=i%32; bs.arr[w]|=(1<<b);
}
function bitsetClear(bs,i){
  if(i<0||i>=bs.n) throw new Error('BIT_OUT_OF_RANGE');
  var w=(i/32)|0, b=i%32; bs.arr[w]&=~(1<<b);
}
function bitsetGet(bs,i){
  if(i<0||i>=bs.n) throw new Error('BIT_OUT_OF_RANGE');
  var w=(i/32)|0, b=i%32; return (bs.arr[w]>>b)&1;
}
function bitsetFlip(bs,i){
  if(i<0||i>=bs.n) throw new Error('BIT_OUT_OF_RANGE');
  var w=(i/32)|0, b=i%32; bs.arr[w]^=(1<<b);
}
function bitsetCount(bs){
  var c=0; for(var i=0;i<bs.words;i++){ var v=bs.arr[i]; while(v){ v&=v-1; c++; } }
  return c;
}
function bitsetOp(a,b,op){
  if(a.n!==b.n) throw new Error('BITSET_SIZE_MISMATCH');
  var r=bitsetCreate(a.n);
  for(var i=0;i<a.words;i++){ r.arr[i]=(op(a.arr[i], b.arr[i]))>>>0; }
  return r;
}
function bitsetOr(a,b){ return bitsetOp(a,b,function(x,y){return x|y;}); }
function bitsetAnd(a,b){ return bitsetOp(a,b,function(x,y){return x&y;}); }
function bitsetXor(a,b){ return bitsetOp(a,b,function(x,y){return x^y;}); }
